#pragma once
#include <JuceHeader.h>
#include "NativeAudioDeviceHost.h"
namespace hem {
// Settings are staged on the control thread; Apply performs an explicit restart.
class DeviceSettingsPanel final : public juce::Component {
public:
 explicit DeviceSettingsPanel(NativeAudioDeviceHost& m):manager(m) {
  for(auto* c:std::initializer_list<juce::Component*>{&refresh,&apply,&note,&driver,&input,&output,&rate,&block,&view})addAndMakeVisible(c);
  driver.setTextWhenNothingSelected("Audio driver");input.setTextWhenNothingSelected("No input");output.setTextWhenNothingSelected("Output device");rate.setTextWhenNothingSelected("Sample rate");block.setTextWhenNothingSelected("Buffer frames");
  view.setViewedComponent(&channels,false);view.setScrollBarsShown(true,false);
  refresh.onClick=[this]{scan();};apply.onClick=[this]{applySettings();};
  driver.onChange=[this]{populateDevices();};input.onChange=[this]{probe();};output.onChange=[this]{probe();};scan();
 }
 void setDeviceChangesAllowed(bool allowed){changesAllowed=allowed;for(auto* c:std::initializer_list<juce::Component*>{&refresh,&apply,&driver,&input,&output,&rate,&block,&channels})c->setEnabled(allowed);if(!allowed)note.setText("Pause playback and finish recording/export before changing audio hardware.",juce::dontSendNotification);}
 void resized()override {auto b=getLocalBounds().reduced(10);auto row=b.removeFromTop(34);refresh.setBounds(row.removeFromLeft(row.getWidth()/2).reduced(2));apply.setBounds(row.reduced(2));note.setBounds(b.removeFromTop(64));driver.setBounds(b.removeFromTop(32).reduced(2));input.setBounds(b.removeFromTop(32).reduced(2));output.setBounds(b.removeFromTop(32).reduced(2));row=b.removeFromTop(32);rate.setBounds(row.removeFromLeft(row.getWidth()/2).reduced(2));block.setBounds(row.reduced(2));view.setBounds(b);layoutChannels();}
private:
 juce::AudioIODeviceType* selectedType(){for(auto* t:manager.getAvailableDeviceTypes())if(t->getTypeName()==driver.getText())return t;return nullptr;}
 void scan(){driver.clear(juce::dontSendNotification);int id=1;for(auto* t:manager.getAvailableDeviceTypes()){t->scanForDevices();driver.addItem(t->getTypeName(),id++);}driver.setText(manager.getCurrentAudioDeviceType(),juce::dontSendNotification);if(driver.getSelectedId()==0&&driver.getNumItems())driver.setSelectedItemIndex(0,juce::dontSendNotification);populateDevices();}
 void populateDevices(){input.clear(juce::dontSendNotification);output.clear(juce::dontSendNotification);input.addItem("No input",1);if(auto* t=selectedType()){const auto setup=manager.getAudioDeviceSetup();input.addItemList(t->getDeviceNames(true),2);output.addItemList(t->getDeviceNames(false),1);input.setSelectedId(1,juce::dontSendNotification);if(setup.inputDeviceName.isNotEmpty())input.setText(setup.inputDeviceName,juce::dontSendNotification);output.setText(setup.outputDeviceName,juce::dontSendNotification);if(output.getSelectedId()==0&&output.getNumItems())output.setSelectedItemIndex(std::max(0,t->getDefaultDeviceIndex(false)),juce::dontSendNotification);}probe();}
 void probe(){inChannels.clear();outChannels.clear();rate.clear(juce::dontSendNotification);block.clear(juce::dontSendNotification);auto* t=selectedType();if(!t)return;std::unique_ptr<juce::AudioIODevice> d(t->createDevice(output.getText(),input.getSelectedId()>1?input.getText():juce::String()));if(!d){note.setText("Select an available input/output device pair.",juce::dontSendNotification);return;}const auto setup=manager.getAudioDeviceSetup();int id=1;for(auto r:d->getAvailableSampleRates())rate.addItem(juce::String(r,0)+" Hz",id++);id=1;for(auto n:d->getAvailableBufferSizes())block.addItem(juce::String(n)+" frames",id++);rate.setText(juce::String(setup.sampleRate,0)+" Hz",juce::dontSendNotification);block.setText(juce::String(setup.bufferSize)+" frames",juce::dontSendNotification);if(!rate.getSelectedId()&&rate.getNumItems())rate.setSelectedItemIndex(0,juce::dontSendNotification);if(!block.getSelectedId()&&block.getNumItems())block.setSelectedItemIndex(0,juce::dontSendNotification);
  auto make=[this](const juce::StringArray& names,juce::OwnedArray<juce::ToggleButton>& list,const juce::BigInteger& mask,const juce::String& prefix){for(int i=0;i<names.size();++i){auto* b=list.add(new juce::ToggleButton(prefix+juce::String(i+1)+": "+names[i]));b->setToggleState(mask[i],juce::dontSendNotification);channels.addAndMakeVisible(b);}};
  if(input.getSelectedId()>1)make(d->getInputChannelNames(),inChannels,setup.inputChannels,"INPUT ");auto mask=setup.outputChannels;if(mask.isZero())mask.setRange(0,std::min(2,d->getOutputChannelNames().size()),true);make(d->getOutputChannelNames(),outChannels,mask,"OUTPUT ");layoutChannels();note.setText("Select up to 128 inputs and one or two outputs. Apply restarts the selected hardware; physical channel names are shown below.",juce::dontSendNotification);
 }
 void layoutChannels(){int y=0;const int width=std::max(240,view.getWidth()-20);for(auto* b:inChannels){b->setBounds(0,y,width,28);y+=28;}for(auto* b:outChannels){b->setBounds(0,y,width,28);y+=28;}channels.setSize(width,std::max(y,view.getHeight()));}
 void applySettings(){if(!changesAllowed)return;NativeAudioDeviceHost::AudioDeviceSetup setup;setup.inputDeviceName=input.getSelectedId()>1?input.getText():juce::String();setup.outputDeviceName=output.getText();setup.sampleRate=rate.getText().getDoubleValue();setup.bufferSize=block.getText().getIntValue();setup.useDefaultInputChannels=setup.useDefaultOutputChannels=false;for(int i=0;i<inChannels.size();++i)setup.inputChannels.setBit(i,inChannels[i]->getToggleState());for(int i=0;i<outChannels.size();++i)setup.outputChannels.setBit(i,outChannels[i]->getToggleState());if(setup.inputChannels.countNumberOfSetBits()>128||setup.outputChannels.countNumberOfSetBits()<1||setup.outputChannels.countNumberOfSetBits()>2){note.setText("Select at most 128 inputs and exactly one or two outputs.",juce::dontSendNotification);return;}if(driver.getText()!=manager.getCurrentAudioDeviceType())manager.setCurrentAudioDeviceType(driver.getText());const auto error=manager.setAudioDeviceSetup(setup,true);note.setText(error.isEmpty()?"Audio device ready: "+juce::String(manager.getAudioDeviceSetup().sampleRate,0)+" Hz / "+juce::String(manager.getAudioDeviceSetup().bufferSize)+" frames":error,juce::dontSendNotification);}
 NativeAudioDeviceHost& manager;bool changesAllowed=true;
 juce::TextButton refresh{"RESCAN AUDIO DEVICES"},apply{"APPLY AUDIO SETTINGS"};juce::Label note;juce::ComboBox driver,input,output,rate,block;juce::Viewport view;juce::Component channels;juce::OwnedArray<juce::ToggleButton> inChannels,outChannels;
};
}
